import random

def solve_for_a(a):
    n = len(a)
    s_i = [set() for _ in range(n)]
    max_abs_sum = 0
    for i in range(n):
        # a[i] can start a subsequence
        s_i[i].add(a[i])
        # or it can follow a subsequence ending at i-1
        if i > 0:
            for s in s_i[i-1]:
                s_i[i].add(s + a[i])
        # or it can follow a subsequence ending at i-2
        if i > 1:
            for s in s_i[i-2]:
                s_i[i].add(s + a[i])

        for s in s_i[i]:
            max_abs_sum = max(max_abs_sum, abs(s))
    return max_abs_sum

def find_min_max_abs_sum(n, iterations=100):
    min_max_abs_sum = float('inf')
    for _ in range(iterations):
        a = [random.choice([1, -1]) for _ in range(n)]
        min_max_abs_sum = min(min_max_abs_sum, solve_for_a(a))
    return min_max_abs_sum

for n in [10, 20, 30, 40, 50]:
    print(f"n={n}, min_max_abs_sum={find_min_max_abs_sum(n)}")
